'use client';

import {
  useCallback,
  useEffect,
  useMemo,
  useState,
} from 'react';

import Player from './Player';
import Room from './Room';
import HUD from './HUD';
import InteractionPanel from './InteractionPanel';
import ChallengeModal from './ChallengeModal';
import ClueJournal from './ClueJournal';

import { challenges } from '@/data/challenges';
import { clues } from '@/data/clues';
import { layouts } from '@/data/layouts';
import { objects } from '@/data/objects';
import { layout1Objects } from '@/data/layout1Objects';
import { layout2Objects } from '@/data/layout2Objects';

import {
  LayoutId,
  RoomObject,
  Direction,
} from '@/data/types';

const SPEED = 0.18;

export default function Game() {

  /*
   * =========================================================
   * GAME STATE
   * =========================================================
   */

  const [layout, setLayout] =
    useState<LayoutId>(1);

  const [pos, setPos] = useState({
    x: 50,
    y: 43,
  });

  /*
   * CHARACTER DIRECTION
   */

  const [direction, setDirection] =
    useState<Direction>('down');

  /*
   * WALKING ANIMATION
   */

  const [walking, setWalking] =
    useState(false);

  const [frame, setFrame] =
    useState(0);

  const [keys, setKeys] =
    useState<Record<string, boolean>>({});

  const [collected, setCollected] =
    useState<string[]>([]);

  const [solved, setSolved] =
    useState<string[]>([]);

  const [interaction, setInteraction] =
    useState<RoomObject | null>(null);

  const [journal, setJournal] =
    useState(false);

  const [challenge, setChallenge] =
    useState<string | null>(null);

  const [choice, setChoice] =
    useState<number | null>(null);

  const [feedback, setFeedback] =
    useState<
      'correct' | 'wrong' | null
    >(null);

  const [finished, setFinished] =
    useState(false);

  /*
   * ROOM TRANSITION
   */

  const [transitioning, setTransitioning] =
    useState(false);

  /*
   * =========================================================
   * ACTIVE CLUES
   * =========================================================
   */

  const activeClues = useMemo(
    () =>
      clues.filter(
        (clue) =>
          clue.layout <= layout &&
          collected.includes(clue.id)
      ),
    [
      layout,
      collected,
    ]
  );

  /*
   * =========================================================
   * ACTIVE CHALLENGES
   * =========================================================
   */

  const activeChallenges = useMemo(
    () =>
      challenges.filter(
        (challengeItem) =>
          challengeItem.layout === layout
      ),
    [layout]
  );

  /*
   * =========================================================
   * ROOM OBJECTS
   * =========================================================
   */

  const visibleObjects = useMemo(() => {

  if (layout === 1) {
    return layout1objects;
  }
    if (layout === 2) {
    return layout2Objects.map((object) => ({
      ...object,
    }));
  }
    return [];

  }, [layout]);

  /*
   * =========================================================
   * FIND NEAREST OBJECT
   * =========================================================
   */

  const nearId = useMemo(() => {

    let best: RoomObject | null = null;

    let bestDistance = 8;

    for (
      const object of visibleObjects
    ) {

      const centerX =
        object.x +
        object.w / 2;

      const centerY =
        object.y +
        object.h / 2;

      const distance =
        Math.hypot(
          pos.x - centerX,
          pos.y - centerY
        );

      if (
        distance < bestDistance
      ) {

        bestDistance =
          distance;

        best = object;
      }
    }

    return best?.id ?? null;

  }, [
    pos,
    visibleObjects,
  ]);

  const nearObj =
    visibleObjects.find(
      (object) =>
        object.id === nearId
    ) ?? null;

  /*
   * =========================================================
   * CURRENT CHALLENGE
   * =========================================================
   */

  const currentChallenge =
    challenges.find(
      (challengeItem) =>
        challengeItem.id === challenge
    ) ?? null;

  /*
   * =========================================================
   * MOVEMENT + COLLISION
   * =========================================================
   */

  const tryMove = useCallback(
    (
      dx: number,
      dy: number
    ) => {

      setPos((current) => {

        const playerW = 2;
        const playerH = 3;

        const collides = (
          x: number,
          y: number
        ) => {

          for (
            const object of visibleObjects
          ) {

            if (!object.solid) {
              continue;
            }

            const collision =
              x + playerW / 2 > object.x &&
              x - playerW / 2 <
                object.x + object.w &&
              y + playerH / 2 > object.y &&
              y - playerH / 2 <
                object.y + object.h;

            if (collision) {
              return true;
            }
          }

          return false;
        };

        /*
         * Move horizontally and vertically separately.
         * This lets the player slide around objects.
         */

        const nx = Math.max(
          6,
          Math.min(
            94,
            current.x + dx
          )
        );

        const xAllowed =
          !collides(
            nx,
            current.y
          );

        const finalX =
          xAllowed
            ? nx
            : current.x;

        const ny = Math.max(
          12,
          Math.min(
            89,
            current.y + dy
          )
        );

        const yAllowed =
          !collides(
            finalX,
            ny
          );

        const finalY =
          yAllowed
            ? ny
            : current.y;

        return {
          x: finalX,
          y: finalY,
        };

      });

    },
    [visibleObjects]
  );

  /*
   * =========================================================
   * KEYBOARD INPUT
   * =========================================================
   */

  useEffect(() => {

    const down = (
      event: KeyboardEvent
    ) => {

      const key =
        event.key.toLowerCase();

      /*
       * PREVENT PAGE SCROLLING
       */

      if (
        key === 'arrowup' ||
        key === 'arrowdown' ||
        key === 'arrowleft' ||
        key === 'arrowright' ||
        key === ' '
      ) {

        event.preventDefault();
      }

      /*
       * SAVE PRESSED KEY
       */

      setKeys((value) => ({
        ...value,
        [key]: true,
      }));

      /*
       * JOURNAL
       */
       if (key === 'escape') {
    event.preventDefault();

    if (interaction && !challenge) {
      setInteraction(null);
    }

    if (journal && !challenge) {
      setJournal(false);
    }

    return;
  }

      if (
        key === 'j' &&
        !interaction &&
        !challenge
      ) {

        setJournal(true);
      }

      /*
       * INTERACTION
       */

      if (
        key === 'e' &&
        nearObj &&
        !interaction &&
        !journal &&
        !challenge
      ) {
    event.preventDefault();
    setJournal(true);
    return;
  }

    };

    const up = (
      event: KeyboardEvent
    ) => {

      const key =
        event.key.toLowerCase();

      setKeys((value) => ({
        ...value,
        [key]: false,
      }));

    };

    window.addEventListener(
      'keydown',
      down
    );

    window.addEventListener(
      'keyup',
      up
    );

    const blur = () => {
      setKeys({});
    };

    window.addEventListener(
      'blur',
      blur
    );

    return () => {

      window.removeEventListener(
        'keydown',
        down
      );

      window.removeEventListener(
        'keyup',
        up
      );

      window.removeEventListener(
        'blur',
        blur
      );

    };

  }, [
    nearObj,
    interaction,
    journal,
    challenge,
  ]);

  /*
   * =========================================================
   * MOVEMENT LOOP
   * =========================================================
   */

  useEffect(() => {

    let animationFrame = 0;

    const updateMovement = () => {

      let dx = 0;
      let dy = 0;

      if (
        keys.w ||
        keys.arrowup
      ) {
        dy -= SPEED;
      }

      if (
        keys.s ||
        keys.arrowdown
      ) {
        dy += SPEED;
      }

      if (
        keys.a ||
        keys.arrowleft
      ) {
        dx -= SPEED;
      }

      if (
        keys.d ||
        keys.arrowright
      ) {
        dx += SPEED;
      }

      /*
       * CHECK WHETHER PLAYER IS MOVING
       */

      const isMoving =
        dx !== 0 ||
        dy !== 0;

      setWalking(isMoving);

      /*
       * CHARACTER DIRECTION
       *
       * Horizontal gets priority
       * when moving diagonally.
       */

      if (dx < 0) {

        setDirection('left');

      } else if (dx > 0) {

        setDirection('right');

      } else if (dy < 0) {

        setDirection('up');

      } else if (dy > 0) {

        setDirection('down');

      }

      /*
       * MOVE PLAYER
       */

      if (
        isMoving &&
        !interaction &&
        !journal &&
        !challenge &&
        !transitioning
      ) {

        tryMove(
          dx,
          dy
        );
      }

      animationFrame =
        requestAnimationFrame(
          updateMovement
        );
    };

    animationFrame =
      requestAnimationFrame(
        updateMovement
      );

    return () => {

      cancelAnimationFrame(
        animationFrame
      );

    };

  }, [
    keys,
    tryMove,
    interaction,
    journal,
    challenge,
    transitioning,
  ]);

  /*
   * =========================================================
   * WALKING ANIMATION
   * =========================================================
   */

  useEffect(() => {

    /*
     * When standing still,
     * always show frame 0.
     */

    if (!walking) {

      setFrame(0);

      return;
    }

    /*
     * Switch between PNG 1 and PNG 2.
     */

    const timer =
      window.setInterval(() => {

        setFrame((current) =>
          current === 0
            ? 1
            : 0
        );

      }, 150);

    return () => {

      window.clearInterval(
        timer
      );

    };

  }, [walking]);

  /*
   * =========================================================
   * LAYOUT 1 → LAYOUT 2
   * =========================================================
   *
   * EXIT:
   *
   * X < 12
   * Y > 82
   *
   * Bottom-left corner.
   */

  useEffect(() => {

    if (layout !== 1) {
      return;
    }

    if (transitioning) {
      return;
    }

    const reachedExit =
      pos.x < 12 &&
      pos.y > 82;

    if (!reachedExit) {
      return;
    }

    setTransitioning(true);

    window.setTimeout(() => {

      setLayout(2);

      setPos({
        x: 50,
        y: 75,
      });

      setDirection('up');

      setInteraction(null);

      setJournal(false);

      setChallenge(null);

      setChoice(null);

      setFeedback(null);

      setTransitioning(false);

    }, 700);

  }, [
    pos.x,
    pos.y,
    layout,
    transitioning,
  ]);

  /*
   * =========================================================
   * CHALLENGE PROGRESSION
   * =========================================================
   */

  useEffect(() => {

    const completed =
      activeChallenges.every(
        (challengeItem) =>
          solved.includes(
            challengeItem.id
          )
      );

    if (
      completed &&
      activeChallenges.length &&
      !transitioning
    ) {

      if (
        layout < 4
      ) {

        const timer =
          window.setTimeout(() => {

            setLayout(
              (layout + 1) as LayoutId
            );

            setPos({
              x: 50,
              y: 43,
            });

            setDirection(
              'down'
            );

            setInteraction(null);

            setJournal(false);

            setChallenge(null);

            setChoice(null);

            setFeedback(null);

          }, 500);

        return () => {

          window.clearTimeout(
            timer
          );

        };

      }

      setFinished(true);
    }

  }, [
    activeChallenges,
    layout,
    solved,
    transitioning,
  ]);

  /*
   * =========================================================
   * COLLECT CLUE
   * =========================================================
   */

  const collect = () => {

    const clue =
      interaction?.clueId
        ? clues.find(
            (clueItem) =>
              clueItem.id ===
              interaction.clueId
          )
        : undefined;

    if (
      clue &&
      clue.layout === layout &&
      !collected.includes(
        clue.id
      )
    ) {

      setCollected(
        (value) => [
          ...value,
          clue.id,
        ]
      );

    }

    setInteraction(null);
  };

  /*
   * =========================================================
   * SUBMIT CHALLENGE
   * =========================================================
   */

  const submit = () => {

    if (
      !currentChallenge ||
      choice === null
    ) {
      return;
    }

    if (
      choice ===
      currentChallenge.answer
    ) {

      setFeedback(
        'correct'
      );

      if (
        !solved.includes(
          currentChallenge.id
        )
      ) {

        setSolved(
          (value) => [
            ...value,
            currentChallenge.id,
          ]
        );

      }

    } else {

      setFeedback(
        'wrong'
      );

    }
  };

  /*
   * =========================================================
   * OPEN NEXT CHALLENGE
   * =========================================================
   */

  const openNextChallenge =
    () => {

      const next =
        activeChallenges.find(
          (challengeItem) =>
            !solved.includes(
              challengeItem.id
            )
        );

      if (next) {

        setChallenge(
          next.id
        );

        setChoice(null);

        setFeedback(null);
      }

    };

  /*
   * =========================================================
   * FINISHED SCREEN
   * =========================================================
   */

  if (finished) {

    return (

      <main className="game-shell flex min-h-screen items-center justify-center p-6">

        <div className="panel max-w-2xl p-10 text-center">

          <div className="text-3xl font-black text-yellow-200">

            CONGRATULATIONS!

          </div>

          <div className="mt-5 text-xl font-black text-cyan-200">

            YOU HAVE COMPLETED THE HEALTHCARE ENGLISH CHALLENGE.

          </div>

          <p className="mt-5 text-sm text-slate-400">

            You explored all four prototype
            layouts and completed all 20
            English challenges.

          </p>

          <button
            className="retro-btn mt-7 px-5 py-3"
            onClick={() =>
              location.reload()
            }
          >

            PLAY AGAIN

          </button>

        </div>

      </main>

    );
  }

  /*
   * =========================================================
   * MAIN GAME
   * =========================================================
   */

  return (

    <main className="game-shell min-h-screen p-3 md:p-6">

      <div className="mx-auto max-w-6xl">

        <div className="mb-2 flex items-center justify-between text-[9px] text-slate-500">

          <span>
            WASD / ARROWS: MOVE
          </span>

          <span>
            E: INTERACT • J: JOURNAL
          </span>

        </div>

        <div className="relative aspect-[4/3] overflow-hidden border-4 border-[#20272e] bg-[#59606a] shadow-2xl">

          <Room
            roomObjects={
              visibleObjects
            }
            nearId={nearId}
            collected={
              new Set(
                collected
              )
            }
            onInteract={(
              object
            ) =>
              setInteraction(
                object
              )
            }
            layout={layout}
          />

          {/* PLAYER */}

          <Player
            x={pos.x}
            y={pos.y}
            direction={direction}
            walking={walking}
            frame={frame}
          />

          <HUD
            layout={layout}
            clues={
              collected.filter(
                (id) =>
                  clues.find(
                    (clueItem) =>
                      clueItem.id ===
                      id
                  )?.layout <=
                  layout
              ).length
            }
            clueTotal={
              layouts[
                layout
              ].clueCount
            }
            done={
              solved.filter(
                (id) =>
                  challenges.find(
                    (
                      challengeItem
                    ) =>
                      challengeItem.id ===
                      id
                  )?.layout ===
                  layout
              ).length
            }
            total={
              layouts[
                layout
              ].challengeCount
            }
            onJournal={() =>
              setJournal(true)
            }
          />

          {nearObj && (

            <div className="absolute bottom-4 left-1/2 z-30 -translate-x-1/2 border-2 border-yellow-300 bg-black/80 px-4 py-2 text-xs font-black text-yellow-100">

              [E] INTERACT —{' '}
              {nearObj.name}

            </div>

          )}

          {transitioning && (

            <div className="absolute inset-0 z-[100] flex items-center justify-center bg-black/70">

              <div className="text-center">

                <div className="text-2xl font-black text-yellow-200">

                  ENTERING NEXT ROOM...

                </div>

                <div className="mt-2 text-xs text-slate-300">

                  LAYOUT 2

                </div>

              </div>

            </div>

          )}

          {interaction && (

            <InteractionPanel
              object={
                interaction
              }
              clue={
                interaction.clueId
                  ? clues.find(
                      (clueItem) =>
                        clueItem.id ===
                          interaction.clueId &&
                        clueItem.layout ===
                          layout
                    )
                  : undefined
              }
              collected={
                !!interaction.clueId &&
                collected.includes(
                  interaction.clueId
                )
              }
              onCollect={
                collect
              }
              onClose={() =>
                setInteraction(
                  null
                )
              }
            />

          )}

          {journal && (

            <ClueJournal
              clues={
                activeClues
              }
              onClose={() =>
                setJournal(
                  false
                )
              }
            />

          )}

          {challenge &&
            currentChallenge && (

              <ChallengeModal
                challenge={
                  currentChallenge
                }
                index={
                  activeChallenges.findIndex(
                    (
                      challengeItem
                    ) =>
                      challengeItem.id ===
                      currentChallenge.id
                  ) + 1
                }
                total={
                  activeChallenges.length
                }
                choice={
                  choice
                }
                setChoice={
                  setChoice
                }
                onSubmit={
                  submit
                }
                feedback={
                  feedback
                }
                onClose={() => {

                  setChallenge(
                    null
                  );

                  setFeedback(
                    null
                  );

                  setChoice(
                    null
                  );

                }}
              />

            )}

        </div>

        <div className="mt-3 flex flex-wrap gap-2">

          <button
            className="retro-btn px-3 py-2 text-[10px]"
            onClick={() =>
              setJournal(true)
            }
          >

            CLUE JOURNAL

          </button>

          <button
            className="retro-btn px-3 py-2 text-[10px]"
            onClick={
              openNextChallenge
            }
            disabled={
              !activeChallenges.some(
                (
                  challengeItem
                ) =>
                  !solved.includes(
                    challengeItem.id
                  )
              ) ||
              collected.filter(
                (id) =>
                  clues.find(
                    (clueItem) =>
                      clueItem.id ===
                      id
                  )?.layout ===
                  layout
              ).length <
                layouts[
                  layout
                ].clueCount
            }
          >

            OPEN NEXT CHALLENGE

          </button>

          <div className="ml-auto px-2 py-2 text-[10px] text-slate-400">

            {
              layouts[
                layout
              ].description
            }

          </div>

        </div>

      </div>

    </main>

  );
}